// Parse Meta webhook payloads for Messenger, Instagram and WhatsApp.
// Emit one item per real inbound customer message with a "status" field:
//   valid  -> continue processing
//   ignore -> business-sent / delivery / read / empty / unsupported (dropped)
//   error  -> incomplete / malformed webhook data (routed to Error Handler)
const out = [];

function pushError(reason, raw) {
  out.push({ json: { status: 'error', error_reason: reason, failed_node: 'Validate Event', raw_event: raw } });
}

for (const item of $input.all()) {
  const body = (item.json && item.json.body) ? item.json.body : item.json;
  if (!body || typeof body !== 'object') { pushError('Meta webhook body missing or not an object', item.json); continue; }

  const object = body.object || '';
  const entries = Array.isArray(body.entry) ? body.entry : [];
  if (entries.length === 0) { pushError('Webhook contained no entry array', body); continue; }

  for (const entry of entries) {
    // ---- WhatsApp Business ----
    if (Array.isArray(entry.changes)) {
      for (const change of entry.changes) {
        const value = change.value || {};
        // delivery / read receipts and status updates -> ignore
        if (Array.isArray(value.statuses) && value.statuses.length) {
          out.push({ json: { status: 'ignore', reason: 'whatsapp status update' } });
          continue;
        }
        const messages = Array.isArray(value.messages) ? value.messages : [];
        const contacts = Array.isArray(value.contacts) ? value.contacts : [];
        for (const m of messages) {
          const text = (m.text && m.text.body) ? String(m.text.body).trim() : '';
          if (m.type && m.type !== 'text') { out.push({ json: { status: 'ignore', reason: 'unsupported whatsapp message type: ' + m.type } }); continue; }
          if (!text) { out.push({ json: { status: 'ignore', reason: 'empty whatsapp message' } }); continue; }
          const contact = contacts[0] || {};
          const mid = m.id;
          const from = m.from;
          if (!mid || !from) { pushError('WhatsApp message missing id or from', m); continue; }
          out.push({ json: {
            status: 'valid',
            raw_channel: 'whatsapp',
            message_id: String(mid),
            customer_id: String(from),
            customer_name: (contact.profile && contact.profile.name) ? contact.profile.name : '',
            customer_message: text,
            conversation_id: String(from),
            message_timestamp: m.timestamp ? new Date(Number(m.timestamp) * 1000).toISOString() : new Date().toISOString(),
          } });
        }
      }
      continue;
    }

    // ---- Messenger (object=page) & Instagram (object=instagram) ----
    const messaging = Array.isArray(entry.messaging) ? entry.messaging : [];
    if (messaging.length === 0) { out.push({ json: { status: 'ignore', reason: 'entry without messaging array (unsupported event type)' } }); continue; }

    for (const ev of messaging) {
      if (ev.delivery) { out.push({ json: { status: 'ignore', reason: 'delivery notification' } }); continue; }
      if (ev.read) { out.push({ json: { status: 'ignore', reason: 'read receipt' } }); continue; }
      const msg = ev.message;
      if (!msg) { out.push({ json: { status: 'ignore', reason: 'unsupported event type (no message)' } }); continue; }
      if (msg.is_echo) { out.push({ json: { status: 'ignore', reason: 'business-sent message (echo)' } }); continue; }
      const text = msg.text ? String(msg.text).trim() : '';
      if (!text) { out.push({ json: { status: 'ignore', reason: 'empty or non-text message' } }); continue; }
      const senderId = ev.sender && ev.sender.id;
      const mid = msg.mid;
      if (!senderId || !mid) { pushError('Messenger/IG event missing sender.id or message.mid', ev); continue; }
      const channel = object === 'instagram' ? 'instagram' : 'messenger';
      out.push({ json: {
        status: 'valid',
        raw_channel: channel,
        message_id: String(mid),
        customer_id: String(senderId),
        customer_name: '',
        customer_message: text,
        conversation_id: String(senderId),
        message_timestamp: ev.timestamp ? new Date(Number(ev.timestamp)).toISOString() : new Date().toISOString(),
      } });
    }
  }
}

if (out.length === 0) out.push({ json: { status: 'ignore', reason: 'no processable events' } });
return out;

const j = $json;

const map = {
  messenger: 'Messenger',
  instagram: 'Instagram',
  whatsapp: 'WhatsApp'
};

// Support both:
// - original webhook field names
// - Store message_id Data Table output field names
const rawChannel = j.raw_channel || j.channel || '';

const channel =
  map[String(rawChannel).toLowerCase()] || 'Unknown';

return {
  json: {
    customer_message:
      j.customer_message || j.original_message || '',

    customer_name:
      j.customer_name || '',

    customer_id:
      j.customer_id,

    channel,

    conversation_id:
      j.conversation_id,

    message_id:
      j.message_id,

    message_timestamp:
      j.message_timestamp || j.event_timestamp
  }
};

const j = $json || {};
const err = j.error || {};
const failed_node = (err.node && err.node.name) || j.failed_node || 'unknown';
const error_message = err.message || j.error_reason || (typeof err === 'string' ? err : JSON.stringify(err)) || 'Unknown workflow error';

// Try to recover context if present
const channel = j.channel || 'Unknown';
const conversation_id = j.conversation_id || (j.raw_event ? '' : '') || 'unknown';

const title = '[Meta Workflow Error] ' + channel + ' \u2014 ' + conversation_id;
const desc =
  'A workflow error occurred while processing a Meta customer-service message.\n\n' +
  'Failed node:\n' + failed_node + '\n\n' +
  'Error message:\n' + error_message + '\n\n' +
  'Channel:\n' + channel + '\n\n' +
  'Conversation ID:\n' + conversation_id + '\n\n' +
  'Customer ID:\n' + (j.customer_id || 'unknown') + '\n\n' +
  'Message ID:\n' + (j.message_id || 'unknown') + '\n\n' +
  'Original message:\n' + (j.customer_message || 'unavailable') + '\n\n' +
  'Execution ID:\n' + $execution.id;

return { json: {
  channel,
  conversation_id,
  customer_id: j.customer_id || 'unknown',
  message_id: j.message_id || ('err_' + $execution.id),
  customer_message: j.customer_message || '',
  message_timestamp: j.message_timestamp || new Date().toISOString(),
  error_message,
  failed_node,
  error_task_title: title,
  error_task_description: desc,
} };

const items = $input.all().map(i => i.json);

function stripHtml(html) {
  return String(html || '')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

const results = [];

function scan(obj) {
  if (!obj) return;

  if (Array.isArray(obj)) {
    for (const item of obj) {
      scan(item);
    }
    return;
  }

  if (typeof obj !== 'object') return;

  // This matches your CMS post structure:
  // title + content + type
  if (obj.title && obj.content) {
    const text = stripHtml(obj.content);

    if (text) {
      results.push({
        source_title: obj.title,
        source_url: obj.url || obj.link || obj.permalink || '',
        source_text: text,
        source_type: obj.type || 'cms'
      });
    }
  }

  // Continue looking through nested objects such as:
  // selling > About Selling > category > posts
  for (const value of Object.values(obj)) {
    if (value && typeof value === 'object') {
      scan(value);
    }
  }
}

for (const item of items) {
  scan(item);
}

if (results.length === 0) {
  return [{
    json: {
      __no_content: true,
      source_title: '',
      source_url: '',
      source_text: '',
      source_type: ''
    }
  }];
}

return results.map(r => ({
  json: r
}));

// Retrieve the most relevant APPROVED CMS sources for each customer message.
// Goal:
// 1. Strongly prioritize title relevance.
// 2. Prefer sources whose source_type matches the user's intent.
// 3. Penalize conflicting source types (e.g. buying source for a selling question).
// 4. Return only 1 source when there is a very strong match.
// 5. Otherwise return maximum 2 sources.

const chunks = $input.all()
  .map(i => i.json)
  .filter(c =>
    c &&
    c.source_text &&
    String(c.source_text).trim() !== ''
  );

const customers = $('Normalize Channel and Message Fields')
  .all()
  .map(i => i.json);

const STOP = new Set([
  'the', 'a', 'an', 'how', 'do', 'i', 'to', 'on', 'in', 'of',
  'and', 'or', 'is', 'are', 'my', 'can', 'you', 'for', 'with',
  'what', 'when', 'where', 'me', 'it', 'this', 'that', 'please',
  'hi', 'hello'
]);

function normalizeWord(word) {
  let w = String(word || '').toLowerCase();

  if (['selling', 'sells', 'sold', 'seller'].includes(w)) return 'sell';
  if (['listing', 'listed', 'lists', 'listings'].includes(w)) return 'list';

  if (['buying', 'buys', 'bought', 'buyer'].includes(w)) return 'buy';

  if (['items'].includes(w)) return 'item';
  if (['products'].includes(w)) return 'product';

  if (['shipping', 'shipped', 'ships'].includes(w)) return 'ship';

  if (['authentication', 'authenticate', 'authenticated', 'authenticating'].includes(w)) {
    return 'authentic';
  }

  if (['sizing', 'sizes', 'sized'].includes(w)) return 'size';

  if (['payments', 'paid', 'paying'].includes(w)) return 'payment';

  if (['returns', 'returned'].includes(w)) return 'return';

  if (['refunds', 'refunded'].includes(w)) return 'refund';

  return w;
}

function tokens(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .map(normalizeWord)
    .filter(w => w && w.length > 2 && !STOP.has(w));
}

function detectIntent(message) {
  const text = String(message || '').toLowerCase();

  if (/\b(sell|selling|seller|list|listing)\b/.test(text)) return 'selling';
  if (/\b(buy|buying|buyer|purchase|checkout)\b/.test(text)) return 'buying';
  if (/\b(ship|shipping|delivery|tracking)\b/.test(text)) return 'shipping';
  if (/\b(authentic|authentication|authenticate|certificate|certification|gia|igi)\b/.test(text)) return 'authentication';
  if (/\b(size|sizing|resize|resizing|ring size)\b/.test(text)) return 'sizing';
  if (/\b(payment|pay|checkout)\b/.test(text)) return 'payment';

  return 'general';
}

function sourceMatchesIntent(sourceType, intent) {
  const type = String(sourceType || '').toLowerCase();

  if (intent === 'selling') return type.includes('selling');
  if (intent === 'buying') return type.includes('buying');
  if (intent === 'shipping') return type.includes('shipping');
  if (intent === 'authentication') {
    return (
      type.includes('authentication') ||
      type.includes('general')
    );
  }
  if (intent === 'sizing') {
    return (
      type.includes('sizing') ||
      type.includes('general')
    );
  }

  return false;
}

function sourceConflictsWithIntent(sourceType, intent) {
  const type = String(sourceType || '').toLowerCase();

  if (intent === 'selling' && type.includes('buying')) return true;
  if (intent === 'buying' && type.includes('selling')) return true;

  return false;
}

const out = [];

for (const cust of customers) {
  const message = String(cust.customer_message || '');
  const qTokens = [...new Set(tokens(message))];
  const intent = detectIntent(message);

  const scored = chunks
    .map(c => {
      const title = String(c.source_title || '');
      const text = String(c.source_text || '');
      const sourceType = String(c.source_type || '');

      const titleTokens = [...new Set(tokens(title))];
      const textTokens = new Set(tokens(text));

      let score = 0;
      let titleMatches = 0;

      // -------------------------
      // Token relevance
      // -------------------------
      for (const token of qTokens) {
        // Title matches are much more important.
        if (titleTokens.includes(token)) {
          score += 6;
          titleMatches += 1;
        }

        // Body matches still matter, but much less.
        if (textTokens.has(token)) {
          score += 1;
        }
      }

      // -------------------------
      // Intent / source-type match
      // -------------------------
      if (sourceMatchesIntent(sourceType, intent)) {
        score += 10;
      }

      if (sourceConflictsWithIntent(sourceType, intent)) {
        score -= 12;
      }

      // -------------------------
      // Strong intent/title boosts
      // -------------------------
      const titleLower = title.toLowerCase();

      if (
        intent === 'selling' &&
        /\b(how.*sell|sell.*platform|selling.*platform)\b/.test(titleLower)
      ) {
        score += 15;
      }

      if (
        intent === 'buying' &&
        /\b(how.*buy|buy.*platform|buying.*platform)\b/.test(titleLower)
      ) {
        score += 15;
      }

      if (
        intent === 'shipping' &&
        /\b(ship|shipping|delivery)\b/.test(titleLower)
      ) {
        score += 10;
      }

      if (
        intent === 'authentication' &&
        /\b(authentic|authentication|certificate|gia|igi)\b/.test(titleLower)
      ) {
        score += 10;
      }

      if (
        intent === 'sizing' &&
        /\b(size|sizing|resize|resizing)\b/.test(titleLower)
      ) {
        score += 10;
      }

      const titleMatchRatio =
        qTokens.length > 0 ? titleMatches / qTokens.length : 0;

      return {
        c,
        score,
        titleMatches,
        titleMatchRatio
      };
    })
    .filter(x => x.score > 0)
    .sort((a, b) => b.score - a.score);

  let selected = [];

  if (scored.length > 0) {
    const best = scored[0];

    // If one source is an excellent title match,
    // send ONLY that source to the AI.
    const strongBestMatch =
      best.score >= 20 &&
      best.titleMatchRatio >= 0.5;

    if (strongBestMatch) {
      selected = [best.c];
    } else {
      // Otherwise allow at most 2 genuinely relevant sources.
      const second = scored[1];

      selected = [best.c];

      if (
        second &&
        second.score >= 8 &&
        second.score >= best.score * 0.6
      ) {
        selected.push(second.c);
      }
    }
  }

  const sources_text = selected
    .map((c, i) =>
      'SOURCE ' + (i + 1) + ':\n' +
      'Title: ' + (c.source_title || '') + '\n' +
      'URL: ' + (c.source_url || '') + '\n' +
      'Type: ' + (c.source_type || '') + '\n' +
      'Content: ' + (c.source_text || '')
    )
    .join('\n\n');

  out.push({
    json: {
      ...cust,

      retrieval_intent: intent,

      sources_json: JSON.stringify(selected),

      sources_text:
        sources_text || 'NO APPROVED SOURCES FOUND',

      candidate_source_titles:
        selected.map(c => c.source_title),

      candidate_source_urls:
        selected.map(c => c.source_url),

      has_candidate_sources:
        selected.length > 0
    }
  });
}

return out;

