parameters.jsCode:
const ai = ($json && $json.output) ? $json.output : $json;
const cust = $('Retrieve Relevant Approved Sources').item.json;

function asArr(v) { return Array.isArray(v) ? v : (v ? [v] : []); }
function num(v) { const n = Number(v); return isNaN(n) ? 0 : n; }

let valid = true;
const problems = [];

if (!ai || typeof ai !== 'object') {
  valid = false;
  problems.push('AI output missing/invalid');
}

const decision = ai && ai.decision ? String(ai.decision) : '';

if (decision !== 'AUTO_REPLY' && decision !== 'ESCALATE') {
  valid = false;
  problems.push('invalid decision');
}

const intent_confidence = num(ai && ai.intent_confidence);
const is_allowlisted = !!(ai && ai.is_allowlisted);
const is_sensitive = !!(ai && ai.is_sensitive);
const source_found = !!(ai && ai.source_found);
const support = ai && ai.source_support_level
  ? String(ai.source_support_level)
  : 'NONE';

const customer_reply = ai && ai.customer_reply
  ? String(ai.customer_reply)
  : '';

const source_titles = asArr(ai && ai.source_titles);

const source_urls = asArr(ai && ai.source_urls)
  .filter(u => u && String(u).indexOf('http') === 0);

// Auto-reply gate: ALL required safety conditions must pass.
// A source URL is NOT required as long as approved source content was found
// and the AI confirms FULL support.
const auto_reply_ok =
  valid &&
  decision === 'AUTO_REPLY' &&
  intent_confidence >= 90 &&
  is_allowlisted === true &&
  is_sensitive === false &&
  source_found === true &&
  support === 'FULL' &&
  customer_reply.trim().length > 0;

const final_route = auto_reply_ok ? 'AUTO_REPLY' : 'ESCALATE';

return {
  json: Object.assign({}, cust, {
    ai_valid: valid,
    validation_problems: problems.join('; '),
    decision: decision || 'ESCALATE',
    intent: (ai && ai.intent) || 'unknown',
    topic: (ai && ai.topic) || 'Unsupported or unclear',
    intent_confidence,
    is_allowlisted,
    is_sensitive,
    source_found,
    source_support_level: support,
    customer_reply,
    source_titles,
    source_urls,
    escalation_reason:
      (ai && ai.escalation_reason) ||
      (valid ? '' : problems.join('; ')),
    ai_summary: (ai && ai.ai_summary) || '',
    recommended_staff_action:
      (ai && ai.recommended_staff_action) || '',
    clickup_task_title:
      (ai && ai.clickup_task_title) || '',
    send_customer_reply:
      ai && ai.send_customer_reply === false ? false : true,
    final_route,
  })
};

const j = $json;

const WHATSAPP_PHONE_NUMBER_ID = 'WHATSAPP_PHONE_NUMBER_ID';

const GRAPH_FB = 'https://graph.facebook.com/v21.0';
const GRAPH_IG = 'https://graph.instagram.com/v21.0';

let url;
let body;

// WhatsApp
if (j.channel === 'WhatsApp') {

  url = GRAPH_FB + '/' + WHATSAPP_PHONE_NUMBER_ID + '/messages';

  body = {
    messaging_product: 'whatsapp',
    to: j.customer_id,
    type: 'text',
    text: {
      body: j.customer_reply
    }
  };

// Instagram
} else if (j.channel === 'Instagram') {

  url = GRAPH_IG + '/me/messages';

  body = {
    recipient: {
      id: j.customer_id
    },
    message: {
      text: j.customer_reply
    }
  };

// Messenger
} else if (j.channel === 'Messenger') {

  url = GRAPH_FB + '/me/messages';

  body = {
    recipient: {
      id: j.customer_id
    },
    messaging_type: 'RESPONSE',
    message: {
      text: j.customer_reply
    }
  };

// Unknown channel
} else {

  throw new Error('Unsupported channel: ' + j.channel);

}

return {
  json: {
    ...j,
    send_url: url,
    send_body: body
  }
};

const j = $json;

// -------------------------
// ACKNOWLEDGEMENT TEXT
// -------------------------

const NORMAL_ACK =
  "Thank you for contacting us. Your message needs review by our support team, so it has been passed to the appropriate team member. They will follow up with you.";

const UPSET_ACK =
  "I’m sorry to hear about your experience. I’ve passed your message and the details you shared to our support team for review. A team member will follow up with you.";


// -------------------------
// DETECT TYPE
// -------------------------

const reason = (j.escalation_reason || '').toLowerCase();
const topic = (j.topic || '').toLowerCase();
const intent = (j.intent || '').toLowerCase();

const blob = (
  reason + ' ' +
  topic + ' ' +
  intent + ' ' +
  (j.customer_message || '')
).toLowerCase();

const isUpset =
  /(complaint|angry|upset|furious|terrible|worst|scam|disappointed|unacceptable)/.test(blob);

const ack_text = isUpset ? UPSET_ACK : NORMAL_ACK;


// -------------------------
// CLICKUP PRIORITY
// 1 = Urgent
// 2 = High
// 3 = Normal
// -------------------------

let priority = 3;

if (
  /(legal|lawsuit|fraud|chargeback|payment dispute|severe complaint)/.test(blob)
) {
  priority = 1;
} else if (
  /(refund|return|order|payout|payment|authentication dispute|tracking|delivery|dispute)/.test(blob)
) {
  priority = 2;
}


// -------------------------
// CHANNEL + CLICKUP DATA
// -------------------------

const channel = j.channel;

const tags = [
  'Meta Inbox',
  'Escalation',
  channel
];

if (j.topic) {
  tags.push(j.topic);
}

const title =
  '[Meta Escalation] ' +
  channel +
  ' — ' +
  (j.intent || 'unknown');


const titles = Array.isArray(j.source_titles)
  ? j.source_titles.join(', ')
  : '';

const urls = Array.isArray(j.source_urls)
  ? j.source_urls.join(', ')
  : '';


// -------------------------
// CLICKUP DESCRIPTION
// -------------------------

const desc =
  'Customer name:\n' +
  (j.customer_name || 'N/A') +

  '\n\nCustomer ID:\n' +
  (j.customer_id || '') +

  '\n\nChannel:\n' +
  channel +

  '\n\nConversation ID:\n' +
  (j.conversation_id || '') +

  '\n\nMessage ID:\n' +
  (j.message_id || '') +

  '\n\nReceived at:\n' +
  (j.message_timestamp || '') +

  '\n\nOriginal customer message:\n' +
  (j.customer_message || '') +

  '\n\nDetected intent:\n' +
  (j.intent || '') +

  '\n\nTopic:\n' +
  (j.topic || '') +

  '\n\nAI confidence:\n' +
  (j.intent_confidence || '') +

  '\n\nEscalation reason:\n' +
  (j.escalation_reason || '') +

  '\n\nAI summary:\n' +
  (j.ai_summary || '') +

  '\n\nRecommended staff action:\n' +
  (j.recommended_staff_action || '') +

  '\n\nSources found:\n' +
  (titles || 'None') +

  '\n\nSource URLs:\n' +
  (urls || 'None');


// -------------------------
// MESSAGE ROUTING
// -------------------------

const WHATSAPP_PHONE_NUMBER_ID = 'WHATSAPP_PHONE_NUMBER_ID';
const INSTAGRAM_IG_USER_ID = 'INSTAGRAM_IG_USER_ID';

const GRAPH_FB = 'https://graph.facebook.com/v21.0';
const GRAPH_IG = 'https://graph.instagram.com/v21.0';

let url;
let body;


// WhatsApp
if (channel === 'WhatsApp') {

  url =
    GRAPH_FB +
    '/' +
    WHATSAPP_PHONE_NUMBER_ID +
    '/messages';

  body = {
    messaging_product: 'whatsapp',
    to: j.customer_id,
    type: 'text',
    text: {
      body: ack_text
    }
  };


// Instagram
} else if (channel === 'Instagram') {

  url =
    GRAPH_IG +
    '/' +
    INSTAGRAM_IG_USER_ID +
    '/messages';

  body = {
    recipient: {
      id: j.customer_id
    },
    message: {
      text: ack_text
    }
  };


// Messenger
} else if (channel === 'Messenger') {

  url =
    GRAPH_FB +
    '/me/messages';

  body = {
    recipient: {
      id: j.customer_id
    },
    messaging_type: 'RESPONSE',
    message: {
      text: ack_text
    }
  };


// Unknown channel
} else {

  throw new Error(
    'Unsupported channel: ' + channel
  );
}


// -------------------------
// OUTPUT
// -------------------------

return {
  json: {
    ...j,

    ack_text: ack_text,

    task_title: title,
    task_description: desc,
    task_priority: priority,
    task_tags: tags,

    send_ack:
      j.send_customer_reply !== false,

    ack_send_url: url,
    ack_send_body: body
  }
};
